        spec: "Willfully threatened to physically injure {V}, a taxi driver, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} received a call: 'Don't pick up fares near here again.' It came from a number tied to {D}. {DL} says it was a wrong number.",
