        defense: [E(.statement, 1, "Wrong Number", "{DL} says it was a wrong number.")],
        role: "Taxi driver",
        exam: [.direct("What is your job?", "\"I drive a taxi, mostly in the evenings, and I wait for fares near a hotel and a bus station.\""), .direct("What call did you get?", "\"A call on my phone from a number I didn't know. A voice said, 'Don't pick up fares near here again.'\""), .direct("Why did that concern you?", "\"I've had problems with another driver over that area, and {DL} had been involved in the earlier case.\""), .direct("Did you recognize the voice?", "\"Yes, I recognized it as {DL}'s from past dealings and from court.\""), .direct("What did you do?", "\"I wrote down the number and time, told my dispatcher, and reported it to the sheriff's office.\""), .direct("What did the call record show?", "\"It showed the call came from a number tied to {DL} at about eight that night.\""), .cross("The caller didn't say who was calling?", "\"No, only the sentence about the fares.\""), .cross("It doesn't mention violence?", "\"It doesn't. It tells me to stay away from the area, and I took it as a warning.\""), .cross("Taxi drivers compete for fares?", "\"Yes, and sometimes tempers flare, but threats are another matter.\""), .cross("You can't be certain of the voice?", "\"I'm fairly sure, though I know phone voices can be hard to identify.\""), .cross("Nothing has happened since the call?", "\"No, but I've been more careful where I park.\"")],
        theory: ("{D} threatened a driver.", "A wrong number."),
        allocution: "\"That was a wrong number, and I'd misheard the voice on the other end. I said what I said in a public place, not aimed at anyone. I'm sorry for frightening {V}.\"",
        truths: ("The caller used {V}'s name.", "The call was placed from a number {DL} had given up weeks earlier."),
        defendant: [.direct("Did you call the driver?", "\"No. I don't know why my number was used. I think it was a wrong number someone dialed from my phone.\""), .direct("Whose phone was it?", "\"Mine, but a friend borrowed it that evening and made some calls. I wasn't paying attention.\""), .direct("What did your friend say?", "\"He said he called a number he thought was a customer. I don't know why it reached the driver.\""), .direct("Did you threaten anyone?", "\"No. I never told anyone to stay away from any area or threatened any driver.\""), .direct("What did you tell the deputy?", "\"I told the deputy my friend borrowed the phone. I gave the deputy his name.\""), .direct("What would you tell the driver?", "\"I'm sorry you were frightened. It wasn't meant for you, and I'd never threaten a driver.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I know people suspect me. I didn't make that call.\""), .cross("The driver recognized your voice?", "\"Maybe, but my friend has a similar voice, and it wasn't me.\""), .cross("The call came from your phone?", "\"It did, and I should have kept it with me.\""), .cross("You've been in disputes with drivers?", "\"Not recently, and never a threat. That's in the past.\""), .cross("You'll watch who uses your phone?", "\"Yes. I won't lend it to anyone from now on.\"")],
        openings: ("{V}, a taxi driver, received a call on {V.his} phone from a number tied to {D}, and a voice said, 'Don't pick up fares near here again.' {V} recognized the voice, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say it was a wrong number and the words were meant for someone else. {D} never knew {V} was the person who answered."),
        closings: ("The call came from {D}'s own number, {V} knew the voice, and the words named the very place {V} waits for fares. After {PRIOR}, {DL} knew who {V} was.", "A voice over a phone is an impression, and a wrong number explains a stray call better than a plan does. The State must prove {D} meant the call for {V}."),
        timeline: [(0, "The call."), (0, "{V} reports it.")],
        identified: "A call record.",
        mood: .wantsConviction)

    static let inspectorAgain = SmallCases.make(
        key: "story.followup.inspectorAgain",
        category: .violent,
        headlines: ["Another Inspector Pushed at Same Property", "Defendant From Code Inspector Case Pushes Again"],
        law: "assaultGovOfficial",
        spec: "Assaulted {V}, a county inspector, while the official was discharging official duties, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} shoved a second inspector on the same property. A camera recorded it. {DL} says the inspector entered without knocking.",
