        defense: [E(.statement, 1, "No Knock", "{DL} says {V} entered without knocking.")],
        role: "Code inspector",
        exam: [.direct("What is your job?", "\"I'm a county code inspector. I check properties for violations and serve inspection orders at addresses with open complaints.\""), .direct("What were you there to do?", "\"I had a written inspection order for the property after the earlier case and was there to check conditions.\""), .direct("What happened?", "\"{DL} came out of the house, argued with me in the yard, and then shoved me in the chest as I tried to explain.\""), .direct("What does your body camera show?", "\"It shows me presenting the order, {DL} yelling, and then pushing me backward with both hands.\""), .direct("What injury did you have?", "\"I stumbled and bruised my shoulder when I hit the porch rail, but I wasn't seriously hurt.\""), .direct("What did {DL} say?", "\"{D.He} said I entered the yard without knocking and surprised {D.him}, which is why {D.he} pushed.\""), .cross("You walked into the yard first?", "\"Yes, because the order allows inspection of the exterior, and I knocked at the gate.\""), .cross("{DL} says you didn't knock?", "\"I did knock at the gate and announced myself. {D.He} may not have heard.\""), .cross("{DL} was upset about earlier inspections?", "\"Yes, there's a history, and {D.he} was agitated when I arrived.\""), .cross("{DL} pushed you once?", "\"Once, with both hands, and then stepped back.\""), .cross("You weren't seriously hurt?", "\"No, just a bruise, and I finished my work after deputies arrived.\"")],
        theory: ("{D} shoved an official.", "No knock."),
        allocution: "\"I didn't hear a knock, and I didn't know who was coming through my gate. I pushed to get the person off my property. I'm sorry to the inspector, and I'll let the county handle the junk pile.\"",
        truths: ("The camera shows two knocks.", "The inspector arrived unannounced in an unmarked car."),
        defendant: [.direct("Why did you push the inspector?", "\"I was startled. {V.He} came into my yard and I thought {V.he} was a trespasser, and I pushed {V.him} away.\""), .direct("Did you know {V.he} was an inspector?", "\"Not at first. {V.He} was coming through the yard and I didn't see a badge until {V.he} spoke.\""), .direct("Did {V.he} knock?", "\"I didn't hear {V.his} knock. I came out because I heard someone in my yard.\""), .direct("Why were you angry?", "\"Because of the earlier inspection. I felt the county was targeting me, and I reacted badly.\""), .direct("What happened after?", "\"I stopped as soon as I saw the uniform. I let him finish his inspection while the deputies came.\""), .direct("What would you tell the inspector?", "\"I'm sorry for pushing you. I was wrong, and I'll let you do your work without any trouble.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I know better than to put my hands on a county employee.\""), .cross("You pushed a county inspector?", "\"I did that, and I regret it more than I can say. {V.He} was only doing {V.his} job.\""), .cross("{V.He} showed you a written order?", "\"I know now that {V.he} did. I didn't read it before I acted.\""), .cross("{V.He} stumbled and hit the rail?", "\"I'm sorry for that. I didn't mean to hurt {V.him}.\""), .cross("You'll cooperate with inspectors?", "\"Yes. I'll let them in and ask questions calmly.\"")],
        openings: ("A county code inspector arrived at the property with a written inspection order after the earlier case over {PRIOR}, and {D} shoved {V}. The inspector's body camera recorded the shove, and {DL} had been before this court in {PRIORDATE}.", "The defense will say the inspector entered without knocking, and {D} reacted to a stranger in the yard. A reflex push is not an assault on an official."),
        closings: ("The inspector held a written order, wore a body camera, and was shoved by {D}. After {PRIOR}, {DL} knew exactly who inspectors are and what they are allowed to do.", "An inspector who enters without knocking startles a homeowner, and {D} pushed once. The State must prove {D} knew the person was an official and meant to resist."),
        timeline: [(0, "The knock."), (0, "The shove.")],
